(() => {
  window.__px = sel => {
    const c = document.querySelector(sel);
    if (!c) return null;
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let n = 0, h = 0; const cols = new Set();
    for (let i = 0; i < d.length; i += 4) {
      if (d[i + 3] > 0) { n++; h = (Math.imul(h, 31) + d[i] * 7 + d[i + 1] * 13 + d[i + 2] * 17 + (i >> 2)) >>> 0; if (cols.size < 4000) cols.add((d[i] << 16) | (d[i + 1] << 8) | d[i + 2]); }
    }
    return { w: c.width, h: c.height, filled: +(n / (d.length / 4)).toFixed(3), colors: cols.size, hash: h };
  };
  const secOf = k => k === 'kitchen' ? document.querySelector('[data-key=kitchen]') : document.querySelector(`.card[data-key='${k}']`);
  const canvasSel = k => k === 'kitchen' ? '#v-kitchen' : `.card[data-key='${k}'] canvas`;
  // real button clicks: idle -> active -> idle, compare pixels
  window.__toggleTest = () => {
    const r = {};
    __focus(); __anim(0);
    for (const k of [...__keys(), 'kitchen']) {
      const sec = secOf(k), sel = canvasSel(k);
      sec.querySelector('[data-state=idle]').click(); __render(); const a = __px(sel);
      sec.querySelector('[data-state=active]').click(); __render(); const b = __px(sel);
      const chip = sec.querySelector('.chip').textContent, pressed = sec.querySelector('[data-state=active]').getAttribute('aria-pressed');
      sec.querySelector('[data-state=idle]').click(); __render(); const c = __px(sel);
      r[k] = { idleVsActiveDiffer: a.hash !== b.hash, backToIdleSame: a.hash === c.hash, chipWhenActive: chip, activePressed: pressed, chipAfter: sec.querySelector('.chip').textContent, filled: a.filled, idleColors: a.colors, activeColors: b.colors, size: a.w + 'x' + a.h };
    }
    return r;
  };
  // real clock: let the page play, sample each canvas a few times
  window.__animTest = async () => {
    const sleep = ms => new Promise(res => setTimeout(res, ms));
    const r = {};
    for (const k of [...__keys(), 'kitchen']) {
      __focus([k]); __state(k, 'active'); __anim(null);
      const t0 = __anim(null), hs = new Set();
      for (let i = 0; i < 6; i++) { await sleep(130); hs.add(__px(canvasSel(k)).hash); }
      r[k] = { distinctFrames: hs.size, ticks: (__anim(null) - t0) };
    }
    __focus(); __state('*', 'idle');
    return r;
  };
  // layout audit: horizontal overflow, clipped text, kitchen labels outside their view
  window.__audit = () => {
    const vw = document.documentElement.clientWidth, out = { scroll: document.documentElement.scrollWidth + ' / ' + innerWidth };
    const vis = el => el.getClientRects().length && !el.closest('[hidden]');
    const name = el => el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\s+/).join('.') : '') + (el.textContent ? ' "' + el.textContent.trim().slice(0, 18) + '"' : '');
    out.outside = [], out.clipped = [], out.wrappedButtons = [];
    for (const el of document.querySelectorAll('body *')) {
      if (!vis(el) || el.closest('.labels')) continue;
      const r = el.getBoundingClientRect();
      if (r.width && (r.right > vw + 0.5 || r.left < -0.5)) out.outside.push(name(el) + ' ' + Math.round(r.left) + '..' + Math.round(r.right));
      const cs = getComputedStyle(el);
      if (el.children.length === 0 && el.textContent.trim() && (el.scrollWidth > el.clientWidth + 1) && cs.overflowX !== 'visible') out.clipped.push(name(el));
      if (el.tagName === 'BUTTON' && r.height > 40) out.wrappedButtons.push(name(el) + ' h=' + Math.round(r.height));
    }
    // text nodes whose box sticks out of an overflow:hidden ancestor
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let t; (t = walker.nextNode());) {
      if (!t.textContent.trim() || !t.parentElement || !vis(t.parentElement) || t.parentElement.closest('script,style,.labels')) continue;
      const rg = document.createRange(); rg.selectNodeContents(t); const tr = rg.getBoundingClientRect();
      for (let a = t.parentElement; a && a !== document.body; a = a.parentElement) {
        const cs = getComputedStyle(a);
        if (cs.overflowX === 'visible' && cs.overflowY === 'visible') continue;
        const ar = a.getBoundingClientRect();
        if (tr.left < ar.left - 0.5 || tr.right > ar.right + 0.5 || tr.top < ar.top - 0.5 || tr.bottom > ar.bottom + 0.5) out.clipped.push('text "' + t.textContent.trim().slice(0, 20) + '" in ' + name(a).slice(0, 40));
        break;
      }
    }
    const lv = document.querySelector('[data-key=kitchen] .view');
    if (lv && vis(lv)) {
      const b = lv.getBoundingClientRect();
      const rs = [...lv.querySelectorAll('.labels span')].filter(s => !s.hidden).map(s => [s.textContent, s.getBoundingClientRect()]);
      out.labelOverlaps = [];
      for (let i = 0; i < rs.length; i++) for (let j = i + 1; j < rs.length; j++) { const a = rs[i][1], c = rs[j][1]; if (a.left < c.right && c.left < a.right && a.top < c.bottom && c.top < a.bottom) out.labelOverlaps.push(rs[i][0] + ' x ' + rs[j][0]); }
      out.labels = [...lv.querySelectorAll('.labels span')].map(s => { const r = s.getBoundingClientRect(); return s.textContent + ': ' + (s.hidden ? 'hidden' : (r.left >= b.left - 0.5 && r.right <= b.right + 0.5 && r.top >= b.top - 0.5 && r.bottom <= b.bottom + 0.5 ? 'inside' : 'CLIPPED l' + Math.round(r.left - b.left) + ' r' + Math.round(b.right - r.right) + ' t' + Math.round(r.top - b.top))); });
    }
    __render();
    out.canvases = [...document.querySelectorAll('canvas')].filter(vis).map((c, i) => {
      if (!c.id) c.id = 'cv' + i;
      const p = __px('#' + c.id), host = c.closest('[data-ref]') || c.closest('[data-key]');
      return (host.dataset.ref || host.dataset.key) + ' ' + p.w + 'x' + p.h + ' filled ' + p.filled + ' colors ' + p.colors;
    });
    return out;
  };
  return 'helpers ok';
})()
